    "lacunas": [
      "A nova duração de usinar corpo pode ser qualquer inteiro não negativo.",
      "As relações de precedência da ficha mencionada não estão disponíveis, portanto não é possível determinar o efeito da duração no término."
    ],
    "motivo": "A duração de usinar corpo foi redefinida sem valor fixo e faltam as precedências necessárias para calcular o término.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "O término novo não está determinado porque a duração alterada é desconhecida e as relações de precedência não foram fornecidas."
    ],
    "motivo": "Sem o término novo calculável, não se determina a variação em relação a D12 nem seu sinal.",
    "unidade": "dia_corrido"
  },
