      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "O custo de referência é R$ 1.650,00, incluindo as parcelas fixas e o apoio de R$ 650,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "O término novo não está determinado; portanto, não se sabe se haverá dias de apoio cobrados além dos já incluídos na base."
    ],
    "motivo": "Há cobrança adicional certa de R$ 25,00 e o apoio preserva o valor base em caso de antecipação, mas eventual extensão adicional depende do término novo.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "A magnitude exata depende de eventual extensão do apoio, que não pode ser apurada sem o término novo."
    ],
    "motivo": "A cobrança adicional de R$ 25,00 garante aumento de pelo menos 2.500 centavos; a política sem crédito impede economia por antecipação, e eventual atraso pode acrescentar custo de apoio.",
    "unidade": "BRL_centavo"
  }
}

